  version "1.0.1"
  sha256 arm:   "4d48a1d705c00ffa4262332ea3e90b878f0c1e1ec38789bca9e37b068bacb338",
         intel: "f7553eb5beddf853fd3bc18dec18a50cf2c4e16162e741e8bc7a109ebffa5057"

